/**
 * Sprite + font loading from public/assets/manifest.json (generated by `npm run art`).
 * Every image is pre-fetched with an <img>; only successfully decoded images are handed to KAPLAY, so a missing or
 * broken file never reaches KAPLAY's loader (which would show its crash screen). Missing keys => registry.has() false
 * => the renderer falls back to coloured shapes.
 */
import type { KAPLAYCtx } from "kaplay";
import type { AssetManifest, SpriteInfo, SpriteRegistry } from "../contracts";
import { FONT } from "../contracts";

/** bitmap font grid block in manifest.json (atlas texels; `filter` defaults to the game-wide nearest filter) */
interface FontGrid {
  src: string;
  gridW: number;
  gridH: number;
  chars: string;
  filter?: "linear" | "nearest";
}

/** manifest.json carries the font grids alongside the contract fields */
interface ManifestFile extends AssetManifest {
  font?: FontGrid;
  /** every bitmap font (sr_font, sr_font_outline); when present it supersedes `font` */
  fonts?: (FontGrid & { key: string })[];
}

const BASE: string = (() => {
  try {
    return (import.meta as unknown as { env?: { BASE_URL?: string } }).env?.BASE_URL ?? "./";
  } catch {
    return "./";
  }
})();

export function assetUrl(src: string): string {
  if (/^(https?:|data:|blob:|\/)/.test(src)) return src;
  return BASE.endsWith("/") ? BASE + src : BASE + "/" + src;
}

function loadImage(url: string, timeoutMs = 15000): Promise<HTMLImageElement | null> {
  return new Promise((resolve) => {
    const img = new Image();
    let done = false;
    const finish = (v: HTMLImageElement | null) => {
      if (done) return;
      done = true;
      resolve(v);
    };
    const t = setTimeout(() => finish(null), timeoutMs);
    img.onload = () => {
      clearTimeout(t);
      finish(img);
    };
    img.onerror = () => {
      clearTimeout(t);
      finish(null);
    };
    img.src = url;
  });
}

export async function fetchManifest(): Promise<ManifestFile | null> {
  try {
    const res = await fetch(assetUrl("assets/manifest.json"), { cache: "no-cache" });
    if (!res.ok) return null;
    const m = (await res.json()) as ManifestFile;
    if (!m || !Array.isArray(m.sprites)) return null;
    return m;
  } catch {
    return null;
  }
}

export interface LoadResult {
  registry: SpriteRegistry;
  loaded: number;
  failed: string[];
  fontLoaded: boolean;
}

export async function loadSpritesAndFont(k: KAPLAYCtx): Promise<LoadResult> {
  const infos = new Map<string, SpriteInfo>();
  const failed: string[] = [];
  const registry: SpriteRegistry = {
    has: (key) => infos.has(key),
    info: (key) => infos.get(key),
  };
  const manifest = await fetchManifest();
  if (!manifest) {
    console.warn("[assets] manifest.json missing - using fallback shapes");
    return { registry, loaded: 0, failed, fontLoaded: false };
  }

  await Promise.all(
    manifest.sprites.map(async (s) => {
      const img = await loadImage(assetUrl(s.src));
      if (!img) {
        failed.push(s.key);
        return;
      }
      try {
        const frames = Math.max(1, s.frames | 0);
        k.loadSprite(s.key, img, {
          sliceX: frames,
          anims: frames > 1 ? { loop: { from: 0, to: frames - 1, loop: s.loop !== false, speed: s.fps ?? 8 } } : undefined,
        });
        infos.set(s.key, s);
      } catch (err) {
        failed.push(s.key);
        console.warn("[assets] loadSprite failed", s.key, err);
      }
    }),
  );

  // fonts: the manifest "fonts" list (sr_font + sr_font_outline) or the legacy single "font" block
  const fontList: (FontGrid & { key: string })[] = manifest.fonts?.length
    ? manifest.fonts
    : manifest.font
      ? [{ ...manifest.font, key: manifest.fontKey ?? FONT }]
      : [];
  const fontKey = manifest.fontKey ?? FONT;
  let fontLoaded = false;
  await Promise.all(
    fontList.map(async (f) => {
      const url = assetUrl(f.src);
      const ok = await loadImage(url);
      if (!ok) return;
      try {
        k.loadBitmapFont(f.key, url, f.gridW, f.gridH, { chars: f.chars, ...(f.filter ? { filter: f.filter } : {}) });
        if (f.key === fontKey) fontLoaded = true;
      } catch (err) {
        console.warn("[assets] font failed", f.key, err);
      }
    }),
  );
  if (failed.length) console.warn(`[assets] ${failed.length} sprite(s) failed to load`, failed.slice(0, 10));
  return { registry, loaded: infos.size, failed, fontLoaded };
}
